mapper.select:
SELECT activity_order.order_no, activity_order.activity_id, activity.title AS activity_title, activity_order.amount_fen, activity_order.status, activity_order.pay_channel, activity_order.pay_time, activity_order.expire_time, activity_order.close_time, activity_order.create_time FROM activity_order LEFT JOIN activity ON activity.id = activity_order.activity_id WHERE activity_order.deleted_flag = 0 AND activity_order.user_id = #{userId}
AND activity_order.status = #{queryForm.status}
AND activity_order.activity_id = #{queryForm.activityId}
ORDER BY activity_order.id DESC

SELECT activity_order.order_no, activity_order.activity_id, activity.title AS activity_title, activity_order.user_id, portal_user.username, activity_order.amount_fen, activity_order.status, activity_order.pay_channel, activity_order.channel_order_no, activity_order.pay_time, activity_order.expire_time, activity_order.close_time, activity_order.create_time FROM activity_order LEFT JOIN activity ON activity.id = activity_order.activity_id LEFT JOIN portal_user ON portal_user.id = activity_order.user_id WHERE activity_order.deleted_flag = 0
AND activity_order.status = #{queryForm.status}
AND activity_order.activity_id = #{queryForm.activityId}
AND activity_order.user_id = #{queryForm.userId}
AND (activity_order.order_no LIKE CONCAT('%', #{queryForm.keyword}, '%') OR activity.title LIKE CONCAT('%', #{queryForm.keyword}, '%') OR portal_user.username LIKE CONCAT('%', #{queryForm.keyword}, '%'))
AND activity_order.create_time >= #{queryForm.beginCreateTime}
AND activity_order.create_time <= #{queryForm.endCreateTime}
ORDER BY activity_order.id DESC

SELECT t.activity_id, activity.title AS activity_title, t.paid_order_count, t.paid_amount_fen, COALESCE(r.refund_order_count, 0) AS refund_order_count, COALESCE(r.refund_amount_fen, 0) AS refund_amount_fen, t.paid_amount_fen - COALESCE(r.refund_amount_fen, 0) AS net_amount_fen FROM ( SELECT activity_order.activity_id, COUNT(*) AS paid_order_count, SUM(activity_order.amount_fen) AS paid_amount_fen FROM activity_order WHERE activity_order.deleted_flag = 0 AND activity_order.status IN (1, 3, 4, 5)
AND activity_order.pay_time >= #{queryForm.beginPayTime}
AND activity_order.pay_time <= #{queryForm.endPayTime}
GROUP BY activity_order.activity_id ) t LEFT JOIN ( SELECT activity_order.activity_id, COUNT(*) AS refund_order_count, SUM(activity_refund.amount_fen) AS refund_amount_fen FROM activity_refund INNER JOIN activity_order ON activity_order.id = activity_refund.order_id WHERE activity_refund.deleted_flag = 0 AND activity_refund.status = 1 AND activity_order.deleted_flag = 0 AND activity_order.status IN (1, 3, 4, 5)
AND activity_order.pay_time >= #{queryForm.beginPayTime}
AND activity_order.pay_time <= #{queryForm.endPayTime}
GROUP BY activity_order.activity_id ) r ON r.activity_id = t.activity_id LEFT JOIN activity ON activity.id = t.activity_id ORDER BY t.paid_amount_fen DESC
